// Bubble-wrapped AND gate. The AND gate input 'in2' is deliberately
// single-stage pipeline-bubbled to create a delay.
module TopModule (
    input  in1,
    input  in2,
    output out
);
    wire and0_out;
    and and0 (and0_out, in1, in2);
    reg and1_out;
    always @(posedge in2) and1_out <= and0_out;
    assign out = and1_out;
endmodule

